// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of [http.ServeMux].
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	http.Handler
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/meetings", wrapper.ListMeetings)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/meetings", wrapper.CreateMeeting)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/v1/meetings/{meetingId}", wrapper.DeleteMeeting)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/meetings/{meetingId}", wrapper.GetMeeting)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/meetings/{meetingId}/retry", wrapper.RetryMeeting)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/meetings/{meetingId}/recording", wrapper.GetRecording)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/v1/meetings/{meetingId}/recording", wrapper.UploadRecording)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/meetings/{meetingId}/transcript", wrapper.GetTranscript)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/meetings/{meetingId}/summary/regenerate", wrapper.RegenerateSummary)
	m.HandleFunc(http.MethodPatch+" "+options.BaseURL+"/v1/action-items/{actionItemId}", wrapper.UpdateActionItem)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/search", wrapper.SearchMeetings)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/healthz", wrapper.GetHealth)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/readyz", wrapper.GetReadiness)

	return m
}
